function ProductsScreen() {
  const spin = useRef(new Animated.Value(0)).current;
  const [items, setItems] = useState<Summary[]>([]);

  useEffect(() => {
    Animated.loop(
      Animated.timing(spin, { toValue: 1, duration: 1000, useNativeDriver: false })
    ).start();
    fetch(PRODUCTS_URL)
      .then((res) => res.text())
      .then((text) => setItems(JSON.parse(text).map(toSummary)));
  }, []);

  return <Spinner rotation={spin} items={items} />;
}
